package com.hosteldekho.controller; import com.hosteldekho.dto.ApiDtos.*; import com.hosteldekho.entity.Enums.*; import com.hosteldekho.service.HostelService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api") public class PublicController { final HostelService s; public PublicController(HostelService x){s=x;} @GetMapping("/colleges") List<CollegeDto> colleges(){return s.colleges();} @GetMapping("/colleges/{slug}") CollegePageDto college(@PathVariable String slug){return s.college(slug);} @GetMapping("/hostels") List<HostelCardDto> search(@RequestParam(required=false)Long collegeId,@RequestParam(required=false)AcType acType,@RequestParam(required=false)GenderType gender,@RequestParam(required=false)Boolean coLiving,@RequestParam(required=false)BigDecimal minPrice,@RequestParam(required=false)BigDecimal maxPrice,@RequestParam(defaultValue="false")boolean onlyVacant,@RequestParam(required=false)String locality,@RequestParam(required=false)Boolean foodIncluded,@RequestParam(required=false)FoodType foodType){return s.search(collegeId,acType,gender,coLiving,minPrice,maxPrice,onlyVacant,locality,foodIncluded,foodType);}@GetMapping("/hostels/{id}") HostelDetailDto detail(@PathVariable Long id){return s.detail(id);}@PostMapping("/rooms/{id}/booking-requests") ResponseEntity<?> book(@PathVariable Long id,@Valid @RequestBody BookingCreateRequest r){s.request(id,r);return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("message","Booking request sent to the hostel manager"));}}
